package queue

// Queue is a FIFO of strings.
type Queue struct{ xs []string }

// Push appends s.
func (q *Queue) Push(s string) { q.xs = append(q.xs, s) }

// Pop removes the first value; ok is false on an empty queue.
func (q *Queue) Pop() (string, bool) {
	if len(q.xs) == 0 {
		return "", false
	}
	s := q.xs[0]
	q.xs = q.xs[1:]
	return s, true
}

